package org.myforeverpet.paradise;
import java.util.Random;
/** Fixed timestep, normalized 160x192 world. No Android dependency. */
public final class Arcade {
 public static final int STAR=0,FLY=1,JUMP=2,FIND=3,DASH=4;public static final int CROWD=48;
 public final int mode;public boolean over,started;public int score,ticks;public float x=48,y=96,vy,steer,targetX=80,targetY=96;
 public final float[] px=new float[5],py=new float[5];private final boolean[] passed=new boolean[5];private final Random rng;private boolean claimed;public int hidden,round=0,wrong=0;public final int[] faces=new int[CROWD];public final float[] cx=new float[CROWD],cy=new float[CROWD];public final int[] props=new int[70];public final float[] propX=new float[70],propY=new float[70];public int theme,lane=1,jumpTicks,slideTicks,coinsFound,coinFlash;public float visualLane=1,distance;public final int[] drawOrder={0,1,2,3,4,5,6,7};public float cameraX=0,cameraY=0,searchZoom=.5f;public final int[] obstacleLane=new int[8],obstacleKind=new int[8];public final float[] depth=new float[8];
 public Arcade(int mode,long seed){this.mode=mode;rng=new Random(seed);if(mode==FIND)shuffle();if(mode==DASH){for(int i=0;i<8;i++){depth[i]=1.1f+i*.35f;obstacleLane[i]=rng.nextInt(3);obstacleKind[i]=rng.nextInt(3);}}if(mode==FLY){for(int i=0;i<5;i++){px[i]=180+i*65;py[i]=55+rng.nextInt(75);}}else if(mode==JUMP){x=80;y=145;vy=-3.8f;for(int i=0;i<5;i++){px[i]=i==0?80:25+rng.nextInt(110);py[i]=165-i*40;}}}
 private void shuffle(){hidden=rng.nextInt(CROWD);theme=rng.nextInt(4);for(int i=0;i<CROWD;i++){faces[i]=i==hidden?-1:rng.nextInt(24);cx[i]=27+(i%6)*53+rng.nextInt(15)-7;cy[i]=79+(i/6)*40+rng.nextInt(13)-6;}for(int i=0;i<props.length;i++){props[i]=rng.nextInt(5);propX[i]=8+rng.nextInt(304);propY[i]=28+rng.nextInt(338);}}
 public void pan(float dx,float dy){if(mode!=FIND)return;cameraX=Math.max(0,Math.min(320-160/searchZoom,cameraX-dx/searchZoom));cameraY=Math.max(0,Math.min(384-192/searchZoom,cameraY-dy/searchZoom));}
 public void zoomSearch(){if(mode!=FIND)return;if(searchZoom<1){searchZoom=1;cameraX=80;cameraY=96;}else{searchZoom=.5f;cameraX=cameraY=0;}}
 public void swipe(float dx,float dy){if(mode!=DASH||over)return;started=true;if(Math.abs(dx)>Math.abs(dy)&&Math.abs(dx)>6)lane=Math.max(0,Math.min(2,lane+(dx>0?1:-1)));else if(dy< -6&&slideTicks==0&&jumpTicks==0)jumpTicks=32;else if(dy>6&&jumpTicks==0&&slideTicks==0)slideTicks=32;}
 public void input(float a,float b){if(over)return;if(mode==DASH){started=true;return;}if(mode==FIND){if(!started){started=true;return;}if(a<0||a>=160||b<28||b>=192)return;float wx=a/searchZoom+cameraX,wy=b/searchZoom+cameraY;int hit=-1;double best=22;for(int i=0;i<CROWD;i++){double d=Math.hypot(cx[i]-wx,cy[i]-wy);if(d<best){best=d;hit=i;}}if(hit<0)return;if(hit==hidden){score++;round++;if(round>=8)over=true;else shuffle();}else{wrong++;if(wrong>=5)over=true;}return;}started=true;if(mode==FLY){vy=-3.4f;}else if(mode==JUMP){steer=Math.max(-1,Math.min(1,(a-x)/24));}else if(Math.hypot(a-targetX,b-targetY)<13){score++;targetX=18+rng.nextInt(124);targetY=30+rng.nextInt(140);}}
 public void release(){steer=0;}
 public void step(){if(over||!started)return;ticks++;if(ticks>=3600&&mode!=DASH){over=true;return;}
 if(mode==FIND){if(ticks>=3600)over=true;return;}
 if(mode==DASH){visualLane+=(lane-visualLane)*.24f;if(coinFlash>0)coinFlash--;if(jumpTicks>0)jumpTicks--;if(slideTicks>0)slideTicks--;float speed=.010f+Math.min(.012f,ticks*.000003f);distance+=speed*1.8f;for(int i=0;i<8;i++){float old=depth[i];depth[i]-=speed;if(old>.12f&&depth[i]<=.12f){if(obstacleLane[i]==lane){if(obstacleKind[i]==2){score+=3;coinsFound++;coinFlash=18;depth[i]=-.13f;}else if((obstacleKind[i]==0&&jumpTicks==0)||(obstacleKind[i]==1&&slideTicks==0)){over=true;return;}else score++;}else score++;}if(depth[i]<-.12f){float far=0;for(float d:depth)far=Math.max(far,d);depth[i]=far+.35f;obstacleLane[i]=rng.nextInt(3);obstacleKind[i]=rng.nextInt(3);}}for(int i=1;i<drawOrder.length;i++){int k=drawOrder[i],j=i-1;while(j>=0&&depth[drawOrder[j]]<depth[k]){drawOrder[j+1]=drawOrder[j];j--;}drawOrder[j+1]=k;}return;}
 if(mode==STAR){if(ticks>=900)over=true;return;}
 if(mode==FLY){vy=Math.min(5,vy+.20f);y+=vy;if(y<9||y>181)over=true;for(int i=0;i<5;i++){px[i]-=1.35f;float gap=Math.max(25,37-score*.4f);if(Math.abs(px[i]-x)<12&&(y-8<py[i]-gap||y+8>py[i]+gap))over=true;if(!passed[i]&&px[i]+9<x-8&&!over){score++;passed[i]=true;}if(px[i]<-12){float max=0;for(float p:px)max=Math.max(max,p);px[i]=max+65;py[i]=55+rng.nextInt(75);passed[i]=false;}}}
 else{float oldY=y;x+=steer*2.5f;if(x<0)x+=160;if(x>160)x-=160;vy+=.13f;y+=vy;for(int i=0;i<5;i++){if(vy>0&&oldY+7<=py[i]&&y+7>=py[i]&&Math.abs(x-px[i])<20){y=py[i]-7;vy=-3.9f;score++;break;}}if(y<75){float delta=75-y;y=75;for(int i=0;i<5;i++){py[i]+=delta;if(py[i]>195){float min=192;for(float p:py)min=Math.min(min,p);py[i]=min-40;px[i]=22+rng.nextInt(116);}}}if(y>202)over=true;}
 }
 public int claim(){if(claimed)return 0;claimed=true;return Economy.reward(mode,score,ticks);}
}
